public class LoyaltyCardTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            LoyaltyCard card = new LoyaltyCard("ann");
            check("brand new card", "ann: BRONZE with 0 pts", card.status());

            check("earn(12050) awards whole points only", 120, card.earn(12050));
            check("after earning", "ann: SILVER with 120 pts", card.status());

            check("earn(50) is under a point", 0, card.earn(50));
            check("earn(-500) ignored", 0, card.earn(-500));
            check("status unchanged by no-op earns", "ann: SILVER with 120 pts", card.status());

            check("canRedeem(121) is false", false, card.canRedeem(121));
            check("canRedeem asks without changing anything", "ann: SILVER with 120 pts", card.status());
            check("redeem(200) refused", false, card.redeem(200));
            check("redeem(0) refused", false, card.redeem(0));

            check("redeem(20) accepted", true, card.redeem(20));
            check("tier still comes from the lifetime total", "ann: SILVER with 100 pts", card.status());

            LoyaltyCard whale = new LoyaltyCard("bob");
            whale.earn(60000);
            whale.redeem(590);
            check("gold tier survives spending the balance", "bob: GOLD with 10 pts", whale.status());
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

