public class LoyaltyCard {

    private final String holder;
    private int balance;
    private int lifetime;

    public LoyaltyCard(String holder) {
        this.holder = holder;
        this.balance = 0;
        this.lifetime = 0;
    }

    public int earn(int cents) {
        if (cents <= 0) {
            return 0;
        }
        int points = cents / 100;
        balance += points;
        lifetime += points;
        return points;
    }

    public boolean canRedeem(int points) {
        return points > 0 && points <= balance;
    }

    public boolean redeem(int points) {
        if (!canRedeem(points)) {
            return false;
        }
        balance -= points;
        return true;
    }

    public String status() {
        String tier;
        if (lifetime < 100) {
            tier = "BRONZE";
        } else if (lifetime < 500) {
            tier = "SILVER";
        } else {
            tier = "GOLD";
        }
        return holder + ": " + tier + " with " + balance + " pts";
    }
}
